						switch (dwType) {
						case 1: 
						case 3: 
						case 7: 
						case 8: 
						case 9: 
							if (dwValue <= 3) dwValue = 3;
							break; 
						}
						if ((iGenLevel <= 2) && (dwValue > 7)) dwValue = 7;

